g localStorage directly.","tree":{"sha":"b723ce815af19055981fefe6a553338d12a4c356","url":"https://api.github.com/repos/KroegerLeif/Alfheim/git/trees/b723ce815af19055981fefe6a553338d12a4c356"},"url":"https://api.github.com/repos/KroegerLeif/Alfheim/git/commits/13a5322628020a19565a40f0d3767067e95f60a2","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/174730541?v=4","events_url":"https://api.github.com/users/KroegerLeif/events{/privacy}","followers_url":"https://api.github.com/users/KroegerLeif/followers","following_url":"https://api.github.com/users/KroegerLeif/following{/other_user}","gists_url":"https://api.github.com/users/KroegerLeif/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/KroegerLeif","id":174730541,"login":"KroegerLeif","node_id":"U_kgDOCmotLQ","organizations_url":"https://api.github.com/users/KroegerLeif/orgs","received_events_url":"https://api.github.com/users/KroegerLeif/received_events","repos_url":"https://api.github.com/users/KroegerLeif/repos","site_admin":false,"starred_url":"https://api.github.com/users/KroegerLeif/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/KroegerLeif/subscriptions","type":"User","url":"https://api.github.com/users/KroegerLeif","user_view_type":"public"},"html_url":"https://github.com/KroegerLeif/Alfheim/commit/13a5322628020a19565a40f0d3767067e95f60a2","node_id":"C_kwDOSdRjLtoAKDEzYTUzMjI2MjgwMjBhMTk1NjVhNDBmMGQzNzY3MDY3ZTk1ZjYwYTI","parents":[{"html_url":"https://github.com/KroegerLeif/Alfheim/commit/6f5b8fd78bd88ac614e9c96ee541d19e9e19951f","sha":"6f5b8fd78bd88ac614e9c96ee541d19e9e19951f","url":"https://api.github.com/repos/KroegerLeif/Alfheim/commits/6f5b8fd78bd88ac614e9c96ee541d19e9e19951f"}],"sha":"13a5322628020a19565a40f0d3767067e95f60a2","url":"https://api.github.com/repos/KroegerLeif/Alfheim/commits/13a5322628020a19565a40f0d3767067e95f60a2"},{"author"