ser confirmation on naming,\nbridge to existing `bidder` field, branch choice, and auth model\nbefore scheduling implementation.","tree":{"sha":"82f8ab1644aa1b8393e7f84705e994060fe3eba7","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/82f8ab1644aa1b8393e7f84705e994060fe3eba7"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/b3077d48ac3bdca614d0011cb7eb9b694e1c231e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/b3077d48ac3bdca614d0011cb7eb9b694e1c231e","node_id":"C_kwDOSddkS9oAKGIzMDc3ZDQ4YWMzYmRjYTYxNGQwMDExY2I3ZWI5YjY5NGUxYzIzMWU","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/e767b9a7b79172f901beb5423c458ed8d4734dc1","sha":"e767b9a7b79172f901beb5423c458ed8d4734dc1","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/e767b9a7b79172f901beb5423c458ed8d4734dc1"}],"sha":"b3077d48ac3bdca614d0011cb7eb9b694e1c231e","url":"https://api.