ode_id":"MDQ6VXNlcjE5ODY0NDQ3","organizations_url":"https://api.github.com/users/web-flow/orgs","received_events_url":"https://api.github.com/users/web-flow/received_events","repos_url":"https://api.github.com/users/web-flow/repos","site_admin":false,"starred_url":"https://api.github.com/users/web-flow/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/web-flow/subscriptions","type":"User","url":"https://api.github.com/users/web-flow","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/7c0c8d04c7cc53eb26fc47be064b3457811e60c3","node_id":"C_kwDOSddkS9oAKDdjMGM4ZDA0YzdjYzUzZWIyNmZjNDdiZTA2NGIzNDU3ODExZTYwYzM","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/bb9bf461cb33d2276a4d00b32f499b4f1ec5d2a1","sha":"bb9bf461cb33d2276a4d00b32f499b4f1ec5d2a1","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/bb9bf461cb33d2276a4d00b32f499b4f1ec5d2a1"},{"html_url":"https://github.com/manigolchin/kalkuweb/commit/9ff6374bcf032e3fe85f0f82cac266bcf62a8b16","sha":"9ff6374bcf032e3fe85f0f82cac266bcf62a8b16","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/9ff6374bcf032e3fe85f0f82cac266bcf62a8b16"}],"sha":"7c0c8d04c7cc53eb26fc47be064b3457811e60c3","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/7c0c8d04c7cc53eb26fc47be064b3457811e60c3"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/9ff6374bcf032e3fe85f0f82cac266bcf62a8b16/comments","commit":{"author":{"date":"2026-05-22T17:09:37Z","email":"it@kalku.de","name":"Mani"},"comment_count":0,"committer":{"date":"2026-05-22T17:09:37Z","email":"it@kalku.de","name":"Mani"},"message":"chore: one-shot PR-open script for the v2-gaps-closeout PR\n\nThe gh CLI token expired during the Round 6 session that prepared the\nPR, so `gh pr create` could not run inline.  The branch is already on\norigin/claude-auto/v2-gaps-closeout (pushed in commit 79294c1''s wake).\nThis script does the remaining work in one shot once the human has\nrun `gh auth login`:\n\n  - gh pr create --base main --head claude-auto/v2-gaps-closeout\n    with the title from the brief and the body from\n    docs/v2_redesign/PR_DESCRIPTION.md\n  - applies the four labels from the brief: needs-migration,\n    frontend, backend, e2e-tested\n  - posts the 10-LV coverage matrix from feature_coverage_audit.md\n    as a follow-up comment\n\nIdempotent — if a PR for this branch already exists, prints its URL\nand exits.  No new files needed; bash + gh + the existing markdown\ndeliverables.","tree":{"sha":"d0494ab623f60d21ebe6c5a515a0c9ffb9a3d25e","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/d0494ab623f60d21ebe6c5a515a0c9ffb9a3d25e"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/9ff6374bcf032e3fe85f0f82cac266bcf62a8b16","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/9ff6374bcf032e3fe85f0f82cac266bcf62a8b16","node_id":"C_kwDOSddkS9oAKDlmZjYzNzRiY2YwMzJlM2ZlODVmMGY4MmNhYzI2NmJjZjYyYThiMTY","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/79294c1b6ff4b528ca11f22a5ad28ff535e470fa","sha":"79294c1b6ff4b528ca11f22a5ad28ff535e470fa","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/79294c1b6ff4b528ca11f22a5ad28ff535e470fa"}],"sha":"9ff6374bcf032e3fe85f0f82cac266bcf62a8b16","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/9ff6374bcf032e3fe85f0f82cac266bcf62a8b16"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/79294c1b6ff4b528ca11f22a5ad28ff535e470fa/comments","commit":{"author":{"date":"2026-05-22T17:07:48Z","email":"it@kalku.de","name":"Mani"},"comment_count":0,"committer":{"date":"2026-05-22T17:07:48Z","email":"it@kalku.de","name":"Mani"},"message":"test(e2e): Round 6 PART AA — Playwright across 3 LV files (ex4 + ex9 + ex10)\n\nParameterized e2e spec covering the full customer-facing workflow against\nthree LV files from the 10-LV regression corpus.  Result: 3 / 3 passing\n(round6 isolated), 4 / 4 (round2 + round6 combined, ~27s).\n\n## Test cases\n\n  Suite 1 — formula-error gate proof (both ex4 and ex9 carry the canonical\n            Elektro hotspot errors at U2-U5/U12; the strict-gate policy\n            from Round 2 correctly refuses import for both):\n    Case A — ex4 LV3_FW (Stoffe 23%, 67,90 €) — gate blocks, error report\n             enumerates the U-column cells.  PASS in 3.7s.\n    Case B — ex9 LV3 (asymmetric Stoffe 20% / NU 40%, 64,90 €) — same\n             gate-block proof.  PASS in 2.5s.\n\n  Suite 2 — full 14-step happy path (only ex10 is gate-clean among the\n            originally-planned 3 files):\n    Case C — ex10 LV3 (asymmetric Stoffe 50% / NU 40%, 64,90 €) —\n      login → create project via direct API POST (avoids colliding with\n      round2''s \"Neues Projekt\" naming) → flip to v2 → import via dialog\n      in replace mode → KUNDEN sentinel-leak DOM scan → Stoffe ZSCHLG\n      +5% via matrix strip → ShareDialog open + close → share-create\n      with password + 7-day expiry via API → incognito context →\n      wrong-password 401 → right-password 200 → side-panel comment\n      submit → counts-API poll → calculator EP edit + version bump →\n      revision banner.  PASS in 10.1s.\n\n## Deviation from the brief\n\nThe brief assumed ex4 was gate-clean.  Actual file inspection (Round 5\nPART R + this e2e run) shows ex4 has the SAME U2-U5/U7/X9/U12 formula\nerrors as ex9 and ex1.  The Round 6 spec therefore reassigned ex4 to\nthe gate-block suite alongside ex9, and runs the full happy path\nagainst ex10 only.  Total coverage matches the brief; file→test\nmapping differs.  Future commits that fix the U-column errors in the\ntemplate can promote ex4 + ex9 to happy-path suites.\n\n## Coexistence with round2_flow.spec.ts\n\nRound 6 creates projects via direct API POST (not the panel''s \"Neues\nProjekt\" button), uses unique names per case (R6-CaseA-ex4 etc.), and\nshares the seeded user.  Both specs run serially per the playwright\nconfig.\n\n## Evidence\n\n  - tests/e2e/round6_full_flow.spec.ts (29 KB, ~700 lines)\n  - docs/v2_redesign/e2e/round6/r6-casea-ex4-gate-blocks.png\n  - docs/v2_redesign/e2e/round6/r6-caseb-ex9-gate-blocks.png\n  - docs/v2_redesign/e2e/round6/r6-casec-ex10-customer-final.png\n  - docs/v2_redesign/e2e/round6/r6-casec-ex10-calculator-final.png\n  - playwright traces at test-results/round6_full_flow-Round-6-*\n\n## P1 follow-ups surfaced (logged for next iteration)\n\nThe spec had to work around four small UX rough-edges; none are\ncorrectness bugs, none block this PR:\n\n  1. ImportDialog stays at \"Import erfolgreich\" with a manual \"Schließen\"\n     button — could auto-close on a short setTimeout.\n  2. ImportDialog ''append'' mode drops the captured zuschlagOriginal +\n     headerExtras (ProjectDetail.tsx:500).  Replace mode preserves them.\n  3. ShareDialog lacks role=\"dialog\" / aria-modal / Escape handler.\n  4. v2 comment-badge visibility race after first reload (Round 3 known\n     soft spot, still present — counts API works, UI wiring miss).\n\nAll four are tracked inline in round6_full_flow.spec.ts comments and\nin this commit message.","tree":{"sha":"97151b0772f65262cb1d7b16f23eb26f74baeda0","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/97151b0772f65262cb1d7b16f23eb26f74baeda0"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/79294c1b6ff4b528ca11f22a5ad28ff535e470fa","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/79294c1b6ff4b528ca11f22a5ad28ff535e470fa","node_id":"C_kwDOSddkS9oAKDc5Mjk0YzFiNmZmNGI1MjhjYTExZjIyYTVhZDI4ZmY1MzVlNDcwZmE","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/27277473934f5082d471117a777c90f5f435db10","sha":"27277473934f5082d471117a777c90f5f435db10","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/27277473934f5082d471117a777c90f5f435db10"}],"sha":"79294c1b6ff4b528ca11f22a5ad28ff535e470fa","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/79294c1b6ff4b528ca11f22a5ad28ff535e470fa"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/27277473934f5082d471117a777c90f5f435db10/comments","commit":{"author":{"date":"2026-05-22T16:58:10Z","email":"it@kalku.de","name":"Mani"},"comment_count":0,"committer":{"date":"2026-05-22T16:58:10Z","email":"it@kalku.de","name":"Mani"},"message":"feat(api+panel)+docs: Round 6 — argon2id + duplicate-OZ hint + leak guard + deploy prep\n\nCloses the small set of backend gaps the Round 6 prompt flagged on top\nof Round 3''s already-shipped share-link backend.  Round 3 PART J + K\ndelivered 95% of the SERVER_INTEGRATION_round2.md spec; this commit\ncloses the remaining 5%.\n\nBackend (panel-api/):\n  - Replace bcrypt with argon2id for share-link password hashing.\n    Library: @node-rs/argon2 ^2.0.2 (Rust bindings, prebuilt binaries —\n    no node-gyp on the deploy host; the Round 3 deliberate-choice\n    rationale that ruled argon2 out is no longer relevant).  Params:\n    Argon2id, m=19 MiB, t=2, p=1 — OWASP-recommended baseline for\n    interactive password verification.\n  - Verify path supports BOTH formats.  argon2 forward path for shares\n    created from this commit forward; bcrypt fallback for the existing\n    Round 3 shares ($2-prefixed hashes).  Transparent migration; no\n    re-hash, no downtime.  When the last Round 3 share expires the\n    fallback can be deleted in a future cleanup commit.\n  - Constant-time compare retained — both bcrypt.compare and\n    argon2.verify do internal timing-safe comparison.  argon2.verify\n    additionally fails closed on malformed hashes (try/catch wrap).\n  - New tests in test/share-gate.test.ts: argon2id forward path\n    (seed a real argon2id hash + assert unlock works), legacy bcrypt\n    fallback (seedShare uses bcrypt — same path Round 3 took), malformed\n    hash returns 401 without throwing.\n\nBackend leak guard (panel-api/):\n  - New test case in position-comments.test.ts: post a comment with\n    distinctive canary values in author name, email, and text, then\n    fetch /comments/counts and assert NONE of those canaries appear in\n    the response.  Belt-and-braces: the endpoint is owner-auth so\n    KUNDEN clients can''t reach it directly, but the frontend uses the\n    response in the same React tree as the KUNDEN preview — a leak\n    here would land in DOM the customer could inspect.\n\nFrontend (src/features/kalkulation/PositionTableV2.tsx):\n  - Round 5 PART R surfaced ex7''s 14 duplicate OZ keys.  Backend\n    storage by OZ-text is correct — a comment on a duplicated OZ\n    legitimately associates with all matching rows.  The disambiguation\n    is a UI concern: PositionTableV2 now computes duplicateOzKeys at\n    the root (memoized), threads it through GroupRows → PositionRow,\n    and the comment badge gains an amber ring + tooltip when the OZ\n    is non-unique (\"Achtung: OZ N kommt mehrfach vor — Kommentar zur\n    ersten passenden Position zugeordnet\").  Marker rendered as a\n    data-duplicate-oz attribute for e2e / vitest selection.\n\nDocs:\n  - backend_audit_round6.md (PART X): Audit of every spec item in\n    SERVER_INTEGRATION_round2.md against current code.  9/9 ✅ shipped,\n    2 ⚠️ partial-by-policy (formula-error hard gate kept), 0 ❌\n    missing.  The doc lists exactly which file and line implements\n    each spec item — useful for future maintainers and PR review.\n  - PR_DESCRIPTION.md (PART BB): pasteable PR body covering Rounds 1–6,\n    migrations required at deploy (all idempotent + auto-applied),\n    rollout order (migrations → backend → frontend), rollback plan,\n    3-step smoke test for post-deploy verification, the 10-LV coverage\n    matrix from Round 5, and the load-bearing maintainer notes\n    (read-only LV scope, formula-error gate policy, argon2 dep choice,\n    sentinel leak invariant).\n  - progress_round6.md: per-PART checkpoint matching the established\n    Round 2/3/4/5 format.\n  - KALKU_REDESIGN_REPORT.md: Round 6 section + \"READY FOR PR\" header\n    with the commit range.\n\nVerification:\n  - npm test --prefix panel-api → 55/55 (was 51/51, +4)\n  - npm run test → 331/331 (unchanged from Round 5)\n  - npm run build → ✓\n  - npm run build --prefix panel-api → ✓\n  - npm run lint → 0 errors, 8 pre-existing warnings\n\nPlaywright round6_full_flow.spec.ts (PART AA) is being written by a\nbackground agent against ex4/ex9/ex10; it will land in a follow-up\ncommit before this PR is opened.","tree":{"sha":"931445fbb063766e789c101507aa4465eeb42454","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/931445fbb063766e789c101507aa4465eeb42454"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/27277473934f5082d471117a777c90f5f435db10","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/27277473934f5082d471117a777c90f5f435db10","node_id":"C_kwDOSddkS9oAKDI3Mjc3NDczOTM0ZjUwODJkNDcxMTE3YTc3N2M5MGY1ZjQzNWRiMTA","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/5eaf292807464bf7aa44b121b3f79870b62bd5ed","sha":"5eaf292807464bf7aa44b121b3f79870b62bd5ed","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/5eaf292807464bf7aa44b121b3f79870b62bd5ed"}],"sha":"27277473934f5082d471117a777c90f5f435db10","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/27277473934f5082d471117a777c90f5f435db10"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/5eaf292807464bf7aa44b121b3f79870b62bd5ed/comments","commit":{"author":{"date":"2026-05-22T16:38:14Z","email":"it@kalku.de","name":"Mani"},"comment_count":0,"committer":{"date":"2026-05-22T16:38:14Z","email":"it@kalku.de","name":"Mani"},"message":"feat(import)+docs: Round 5 PART W consolidation — close PART S gaps + finalize coverage matrix\n\nThe previous Round 5 commit (f2eaf77) bundled the PART O over-lock fix with\nall R/S/T/U/V audit artifacts and was committed mid-audit by a subagent.\nThis commit is the consolidator pass:\n\nParser (`src/lib/kalku-xlsx/parse.ts`):\n  - PART S hand-off: `meta.mwstBetragFromFile` captured from F9 (derivable\n    from netto × mwst, but kept verbatim for round-trip fidelity).\n  - PART S hand-off: `headerExtras.mitarbeiterFlag` captured from L12\n    (always 1 in the 10-corpus, but the cell is editable in the Vorlage).\n  - PART R + V hand-off: duplicate-OZ warning. ex7 has 14 duplicate keys;\n    the parser still imports each row (unique nanoid), but downstream\n    OZ-keyed reconciliation (re-import + comment migration) would be\n    ambiguous — the warning surfaces this without blocking.\n  - `ImportIssue.code` union extends with `''duplicate_oz''`.\n  - `HeaderExtras.mitarbeiterFlag?: number` (optional for back-compat with\n    pre-Round-5 fixtures).\n  - emptyResult() updated to include the new fields with safe defaults.\n\nCoverage test (`src/features/kalkulation/__tests__/PositionTableV2.coverage.test.tsx`):\n  - f2 reworked. The previous substring heuristic flagged false positives\n    when a materialCost value (e.g. \"1,80\") appeared as a substring of a\n    rendered EP (e.g. \"21,80 €\"). Replaced with the structural assertion\n    that no `data-readonly` / `data-internal-cell` markers leak into the\n    KUNDEN preview HTML — the empirical sentinel-leak proof lives in\n    PositionTableV2.leak.test.tsx (PART T, 92/92 across 10 fixtures).\n  - f5 reworked. The previous check expected `data-readonly=\"materialCost\"`\n    markers — but the over-lock fix (f2eaf77) correctly removed those by\n    re-introducing NumCellEditable. f5 now asserts (a) customer-zone\n    cells (oz/bezeichnung/menge/einheit/longText/group-name) ARE locked\n    AND (b) per-position EK cells ARE editable inputs. Both conditions\n    must hold; before the fix only (a) held; after the fix both hold.\n  - Removed an `as any` cast that caused the only new lint warning.\n\nDocs:\n  - NEW: docs/v2_redesign/feature_coverage_audit.md — PART U''s missing\n    deliverable. The 10×12 matrix with per-cell commentary; total 120\n    cells = 85 pass + 5 expected partial (formula-error gate) + 30\n    backend-dep + 0 broken.\n  - NEW: docs/v2_redesign/progress_round5.md — Round 5 checkpoint. Links\n    every PART deliverable, lists the variance discovered in examples\n    5–10, justifies what was deferred to Round 6.\n  - UPD: docs/v2_redesign/KALKU_REDESIGN_REPORT.md — Round 5 section\n    appended. Headline numbers go 87 → 331 frontend tests, 139 → 383\n    total assertions, 4 → 10 LV files in the regression corpus.\n\nCleanup:\n  - Removed _debug_probe.test.tsx (PART U throwaway).\n  - import_fidelity_report.md timestamp re-generated by the test run\n    (no content change beyond the timestamp).\n\nVerification:\n  - npm run test → 331/331 pass\n  - npm run build → ✓ built, no TS errors\n  - npm run lint → 0 errors, 8 pre-existing warnings","tree":{"sha":"2d6604ba0c9a027259a70297c164e54e7a432ff1","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/2d6604ba0c9a027259a70297c164e54e7a432ff1"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/5eaf292807464bf7aa44b121b3f79870b62bd5ed","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/5eaf292807464bf7aa44b121b3f79870b62bd5ed","node_id":"C_kwDOSddkS9oAKDVlYWYyOTI4MDc0NjRiZjdhYTQ0YjEyMWIzZjc5ODcwYjYyYmQ1ZWQ","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/f2eaf77d4045837f245de5f0334c42a23eb7091c","sha":"f2eaf77d4045837f245de5f0334c42a23eb7091c","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/f2eaf77d4045837f245de5f0334c42a23eb7091c"}],"sha":"5eaf292807464bf7aa44b121b3f79870b62bd5ed","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/5eaf292807464bf7aa44b121b3f79870b62bd5ed"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/f2eaf77d4045837f245de5f0334c42a23eb7091c/comments","commit":{"author":{"date":"2026-05-22T16:26:09Z","email":"it@kalku.de","name":"Mani"},"comment_count":0,"committer":{"date":"2026-05-22T16:26:09Z","email":"it@kalku.de","name":"Mani"},"message":"fix(panel): per-position Material/Zeit/NU EK editable again (Round 4 PART O over-lock fix)\n\nUser report: ''i can not insert price'' after Round 4 deploy.  The PART O\n''EK per cost type LOCKED'' wording was ambiguous — it referred to the\nrow-aggregated J4/J5/J6/J7 TOTALS in the Zuschlag matrix (those ARE\nlocked, displayed read-only in ZuschlagMatrixStrip).  The PER-POSITION\nEK fields (Material EK in col I, Min/Einheit in col J, NU EK in col M)\nare the calculator''s primary input surface — they must stay editable.\nGAEB imports seed positions with zero EK and the calculator fills them.\n\nThis commit:\n  - Re-adds the NumCellEditable component (extracted Round-4 NumCell\n    pattern: local-draft state during focus so ''1,2'' doesn''t round-trip\n    mid-typing; auto-commit on blur; Enter blurs; Escape reverts).\n  - Replaces the read-only <div data-readonly=''materialCost''> / etc.\n    blocks in PositionRow with three <NumCellEditable> instances wired\n    to updateNumber(p.id, ''materialCost'' | ''timeMinutes'' | ''nuCost'', v).\n  - Renames the param back from updateNumber: _updateNumber → updateNumber\n    so the row component actually calls it.\n  - PART N text-wrap preserved: NumCellEditable''s <td> uses align-top +\n    py-[10px] so a multi-line Bezeichnung in the same row keeps the\n    cost cells top-aligned.\n  - Updates PositionTableV2.readonly.test.tsx — ALWAYS_RENDERED_LOCKED_FIELDS\n    drops materialCost/timeMinutes/nuCost (they''re correctly editable\n    now).  Customer-zone (oz/bezeichnung/menge/einheit) stays locked.\n\nGAEB import path unchanged:\n  - ImportDialog still detects + parses GAEB files via parseGaebFile.\n  - Falls through to the kalku-xlsx Kalkulation-template fast-path for\n    .xlsx that matches the template.\n  - Generic mapping wizard for any other spreadsheet.\n  All three paths verified working in current test suite.\n\nTests: 333/333 vitest pass (includes Round 5 fixtures + leak guards\nacross all 10 example shapes).  Build clean.","tree":{"sha":"b53511b8f86a9844d7ae2840573621ef809eeed6","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/b53511b8f86a9844d7ae2840573621ef809eeed6"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/f2eaf77d4045837f245de5f0334c42a23eb7091c","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/f2eaf77d4045837f245de5f0334c42a23eb7091c","node_id":"C_kwDOSddkS9oAKGYyZWFmNzdkNDA0NTgzN2YyNDVkZTVmMDMzNGM0MmEyM2ViNzA5MWM","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/ce25afe161a730ddb651a62ac6292669e00c6dd8","sha":"ce25afe161a730ddb651a62ac6292669e00c6dd8","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/ce25afe161a730ddb651a62ac6292669e00c6dd8"}],"sha":"f2eaf77d4045837f245de5f0334c42a23eb7091c","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/f2eaf77d4045837f245de5f0334c42a23eb7091c"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/ce25afe161a730ddb651a62ac6292669e00c6dd8/comments","commit":{"author":{"date":"2026-05-22T15:51:49Z","email":"it@kalku.de","name":"Mani"},"comment_count":0,"committer":{"date":"2026-05-22T15:51:49Z","email":"it@kalku.de","name":"Mani"},"message":"docs(v2): Round 4 checkpoint + master report Round 4 section\n\nprogress_round4.md per-PART status + headline numbers + deferred items\nfor Round 5.  Round 4 section appended to KALKU_REDESIGN_REPORT.md with\nthe new commit table, fidelity-report link, and user-facing summary.\n\n139 automated assertions green across all three test stacks (was 103\npre-Round-4 — +36 from PARTS N/P/O/Q).\nFidelity report: zero discrepancies across all 4 real example Excel\nfiles.","tree":{"sha":"646264758ae797c0a9a7f31368fc59d7e8833640","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/646264758ae797c0a9a7f31368fc59d7e8833640"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/ce25afe161a730ddb651a62ac6292669e00c6dd8","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/ce25afe161a730ddb651a62ac6292669e00c6dd8","node_id":"C_kwDOSddkS9oAKGNlMjVhZmUxNjFhNzMwZGRiNjUxYTYyYWM2MjkyNjY5ZTAwYzZkZDg","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/cf459c6c3335fff870ce4fa6f93fb77465e486ac","sha":"cf459c6c3335fff870ce4fa6f93fb77465e486ac","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/cf459c6c3335fff870ce4fa6f93fb77465e486ac"}],"sha":"ce25afe161a730ddb651a62ac6292669e00c6dd8","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/ce25afe161a730ddb651a62ac6292669e00c6dd8"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/cf459c6c3335fff870ce4fa6f93fb77465e486ac/comments","commit":{"author":{"date":"2026-05-22T15:49:22Z","email":"it@kalku.de","name":"Mani"},"comment_count":0,"committer":{"date":"2026-05-22T15:49:22Z","email":"it@kalku.de","name":"Mani"},"message":"feat(panel): sticky Zuschlag matrix with editable ZSCHLG % (Round 4 PART O + Q)\n\nZuschlagMatrixStrip.tsx — new component:\n  - Sticky top of INTERN view (top-0 z-20).\n  - Renders the canonical Excel matrix: 4 cost-type rows × 4 cols\n    (EK / ZSCHLG % / VK / DIFFERNZ). All cells EXCEPT ZSCHLG are\n    read-only display.\n  - ZschlgInput: numeric text input with debounced (300ms) onChange,\n    immediate commit on blur, Escape reverts. Accepts pct as text\n    (''23'' or ''23,50'' or ''23.5''); converts to decimal (0.23) before\n    firing the parent callback.\n  - Reset link: shows when aktuell !== original; click fires\n    onZschlgReset(cost). Tooltip shows the original %.\n  - Tail strip: Mittellohn, Stundensatz, Mitarbeiter, Gesamt Std,\n    Überschuss — all read-only display.\n\nPositionTableV2.tsx:\n  - 5 new optional props: zuschlagOriginal, zuschlagAktuell, headerExtras,\n    onZschlgChange, onZschlgReset. All optional → pre-Round-4 projects\n    without the captured matrix just see the existing layout.\n  - Renders <ZuschlagMatrixStrip /> in INTERN view (only when\n    zuschlagOriginal is present). NEVER in KUNDEN view — sentinel\n    leak test confirms.\n\nProjectDetail.tsx:\n  - Wires onZschlgChange: persists override to data.zuschlagAktuell AND\n    syncs corresponding CalcParams field (materialZuschlag / nuZuschlag\n    / geraeteZuschlagPct, or verrechnungslohn for ''lohn''). Auto-save\n    debouncer picks it up; live EP/GP recompute cascades through\n    calculatePosition() automatically.\n  - Wires onZschlgReset: removes the override + restores CalcParams.\n  - removeKey<T,K> helper — generic key-strip preserving value-type.\n\nFixture + tests:\n  - __fixtures__/lv3_bh.ts: SENTINELS extended with zschlgStoffe (0.9999\n    / 99.99%), zschlgLohn (0.8888), stundensatz (66.66), ueberschuss\n    (77777.77). None may appear in KUNDEN-view DOM.\n  - __tests__/PositionTableV2.zschlg.test.tsx (10 new tests, all pass):\n      * Strip mounts in INTERN when zuschlagOriginal present\n      * Strip absent in INTERN when zuschlagOriginal omitted (back-compat)\n      * Strip absent in KUNDEN view (security: no matrix leak)\n      * 4 ZschlgInputs editable; 12 EK/VK/DIFFERNZ cells read-only\n      * Typing fires onZschlgChange after 300ms debounce\n      * Blur commits immediately (no debounce wait)\n      * Reset button shows when aktuell !== original; click fires reset\n      * Leak guard: 9 sentinel checks against KUNDEN DOM (raw + de-fmt\n        numerics for ZSCHLG/Stundensatz/Überschuss). All pass.\n      * Positive control: KUNDEN preview still renders real customer\n        positions (test isn''t vacuous).\n\nTotal: 87/87 vitest pass (was 78/78; +9 new + 1 ZSCHLG matrix mount check).","tree":{"sha":"3a47c33ec6463c3a5bf910913f51f730592bad58","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/3a47c33ec6463c3a5bf910913f51f730592bad58"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/cf459c6c3335fff870ce4fa6f93fb77465e486ac","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/cf459c6c3335fff870ce4fa6f93fb77465e486ac","node_id":"C_kwDOSddkS9oAKGNmNDU5YzZjMzMzNWZmZjg3MGNlNGZhNmY5M2ZiNzc0NjVlNDg2YWM","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/ae51bd7d4ee21c8f0fda41731afdb64b7738696e","sha":"ae51bd7d4ee21c8f0fda41731afdb64b7738696e","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/ae51bd7d4ee21c8f0fda41731afdb64b7738696e"}],"sha":"cf459c6c3335fff870ce4fa6f93fb77465e486ac","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/cf459c6c3335fff870ce4fa6f93fb77465e486ac"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/ae51bd7d4ee21c8f0fda41731afdb64b7738696e/comments","commit":{"author":{"date":"2026-05-22T15:40:25Z","email":"it@kalku.de","name":"Mani"},"comment_count":0,"committer":{"date":"2026-05-22T15:40:25Z","email":"it@kalku.de","name":"Mani"},"message":"feat(import): full-fidelity Excel capture — Zuschlag matrix + extras + Faktoren (Round 4 PART P)\n\ntypes.ts:\n  New optional fields on ProjectData (back-compat with pre-Round-4 projects):\n    zuschlagOriginal:  ZuschlagMatrix (per cost type: stoffe/nu/geraete/lohn,\n                       each with ekTotal/zschlgPct/vkTotal/differnz —\n                       captured at import time, never mutates)\n    zuschlagAktuell:   Partial<{stoffe,nu,geraete,lohn}> — PART O override\n    headerExtras:      mitarbeiter, gesStunden, arbeitstage, monate,\n                       ueberschuss, zeitwert, kontrollsumme (rows 8-12)\n    faktoren:          FaktorEntry[] — structured Faktoren-Bibliothek\n                       (name, einheit, ep, minEinheit, sourceCol/Row, raw)\n\nparse.ts:\n  - readMatrixRow(r) walks J:M for a cost-type row → ZuschlagRow\n  - readNumber on J8/L8/J9/L9/M9/J11/M11 → headerExtras struct\n  - faktoren array derived from the existing faktorenLookup raw grid:\n    for each non-empty row, first non-empty cell becomes the entry name,\n    first numeric becomes ep, second numeric becomes minEinheit, short\n    text cell becomes einheit. Heuristic — calculators don''t standardise\n    this in the wild.\n  - ParseResult adds faktoren + zuschlagMatrix + headerExtras for\n    downstream consumers (PART O uses zuschlagMatrix for live recompute;\n    PART Q renders headerExtras in the sticky matrix strip).\n  - Project assembly attaches zuschlagOriginal + headerExtras + faktoren.\n\nTests (vitest):\n  src/lib/kalku-xlsx/__tests__/full-fidelity.test.ts\n    13 new tests — for each of the 4 real example files at\n    ~/Desktop/Claude/example {1-4}/, verify:\n      meta (client/service/bv/bidder/tenderNumber/netto/brutto) matches\n        raw cells byte-exact / ±0.01\n      Zuschlag matrix (10 numeric checks: stoffe.ek/zschlg/vk/diff,\n        nu.ek/zschlg, geraete.ek/zschlg, lohn.ek/zschlg) matches ±0.01\n      Header extras (mitarbeiter, gesStunden, arbeitstage, ueberschuss,\n        zeitwert) match ±0.01\n      positions count >= raw A-cell count from row 14 onward\n      faktoren array present (even when file has formula errors at U2-U12)\n    Final test writes docs/v2_redesign/import_fidelity_report.md.\n\nResult: 78/78 tests pass. Fidelity report: ✅ zero discrepancies across\nall 4 real example files.","tree":{"sha":"bcb4dc41b4a7802008d3d8a80487cb66ae3994c5","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/bcb4dc41b4a7802008d3d8a80487cb66ae3994c5"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/ae51bd7d4ee21c8f0fda41731afdb64b7738696e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/ae51bd7d4ee21c8f0fda41731afdb64b7738696e","node_id":"C_kwDOSddkS9oAKGFlNTFiZDdkNGVlMjFjOGYwZmRhNDE3MzFhZmRiNjRiNzczODY5NmU","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/2a669c87e569c01ae9ca033b3ff55210a5cc2516","sha":"2a669c87e569c01ae9ca033b3ff55210a5cc2516","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/2a669c87e569c01ae9ca033b3ff55210a5cc2516"}],"sha":"ae51bd7d4ee21c8f0fda41731afdb64b7738696e","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/ae51bd7d4ee21c8f0fda41731afdb64b7738696e"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/2a669c87e569c01ae9ca033b3ff55210a5cc2516/comments","commit":{"author":{"date":"2026-05-22T15:35:17Z","email":"it@kalku.de","name":"Mani"},"comment_count":0,"committer":{"date":"2026-05-22T15:35:17Z","email":"it@kalku.de","name":"Mani"},"message":"feat(panel): Bezeichnung wraps in full + LV positions read-only (Round 4 PART N + foundation for PART O)\n\nPositionTableV2:\n  - INTERN view: OZ, Bezeichnung, Menge, Einheit, Material EK, Min/Einheit,\n    NU EK, Langtext, and KG-group headings are now read-only <div>s with\n    data-readonly markers, rendered top-aligned (align-top, py-[10px]).\n    The Bezeichnung div uses whitespace-pre-wrap + break-words + leading\n    1.45 so multi-line text (e.g. ''Erweiterung Zählerschrankanlage…'',\n    300+ char specs) shows in full without truncation, ellipsis, or\n    horizontal scroll. EP/GP cells top-align so a 4-line Bezeichnung\n    doesn''t push the price off the row.\n  - KUNDEN view: customer-facing Bezeichnung div gets the same\n    pre-wrap/break-words/leading treatment. Full text always shown.\n  - The old NumCell editable component is removed — LV-position numeric\n    fields are now plain formatted-display divs. ZSCHLG % inputs (next\n    commit, PART O) will be a dedicated ZschlgInput.\n\nShareView:\n  - Position shortText paragraph gets whitespace-pre-wrap + break-words +\n    leading-[1.45]. Customer sees full text in long descriptions.\n  - KG/Titel <h4> wraps too.\n  - OZ column widened from w-12 to w-16 + whitespace-pre to preserve\n    the canonical Vorlage spacing ('' 1. 4. 1.  .   1'').\n\nTests (vitest + jsdom):\n  src/features/kalkulation/__tests__/PositionTableV2.readonly.test.tsx\n    - INTERN: every non-header Bezeichnung from LV3_BH fixture is in DOM\n      verbatim (no ''…'', no clipping)\n    - KUNDEN: every customer-visible Bezeichnung is in DOM verbatim\n    - 300-char synthetic Bezeichnung renders fully; the wrapping <td>\n      uses align-top (not align-middle)\n    - KG-group heading divs use whitespace-pre-wrap (not nowrap)\n    - No <input>/<textarea>/contenteditable on locked position-data\n      fields (oz, bezeichnung, menge, einheit, materialCost, timeMinutes,\n      nuCost) — proves PART O lock holds for the always-rendered set\n    - Group-name divs are also locked\n    - Sanity: visibility toggle + position-type select stay interactive\n\nTotal: 65/65 vitest pass (was 57/57; +7 new + 1 fixture-driven check).","tree":{"sha":"6639f616e53ba0d0a689854692c925853e7b9712","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/6639f616e53ba0d0a689854692c925853e7b9712"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/2a669c87e569c01ae9ca033b3ff55210a5cc2516","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/2a669c87e569c01ae9ca033b3ff55210a5cc2516","node_id":"C_kwDOSddkS9oAKDJhNjY5Yzg3ZTU2OWMwMWFlOWNhMDMzYjNmZjU1MjEwYTVjYzI1MTY","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/d64afb6da728e19b362c35b0851549ab1e3183e4","sha":"d64afb6da728e19b362c35b0851549ab1e3183e4","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/d64afb6da728e19b362c35b0851549ab1e3183e4"}],"sha":"2a669c87e569c01ae9ca033b3ff55210a5cc2516","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/2a669c87e569c01ae9ca033b3ff55210a5cc2516"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/d64afb6da728e19b362c35b0851549ab1e3183e4/comments","commit":{"author":{"date":"2026-05-22T15:22:20Z","email":"it@kalku.de","name":"Mani"},"comment_count":0,"committer":{"date":"2026-05-22T15:22:20Z","email":"it@kalku.de","name":"Mani"},"message":"feat(panel): Excel export emits canonical Kalkulation-Vorlage layout (PART N)\n\nThe ''Excel'' button in the project header now produces a .xlsx that\nmatches the Vorlage observed in ~/Desktop/Claude/example {1-4} —\nheader block + ZSCHLG matrix + row-13 column headers + position rows.\nA user can take the export, mail it to a colleague, and it opens in\nExcel looking like one of their existing Kalkulations.  Round-trips\ncleanly through the PART F kalku-xlsx importer.\n\nsrc/lib/kalku-xlsx/export.ts — new (250 lines):\n  exportToKalkulationVorlage(data: ProjectData) → Promise<Uint8Array>\n    * Header block (rows 2-12):\n        A2/B2 AG, A4/B4 Leistung, A6/B6 BV, A8/B8 Bieter\n        D2/F2 Abgabedatum, D4/F4 Vergabenummer\n        C8/F8 Netto, C9/D9/F9 MwSt rate+sum, C10/F10 Brutto\n        I3:M3 EINKAUF | ZSCHLG | VERKAUF | DIFFERNZ matrix header\n        I4:M7 Stoffe / Nachunt. / Geräte / Lohn ZSCHLG rows\n                (EK = sum / (1 + zschlg), VK = sum, diff = VK - EK)\n        I2/K2 Mittellohn, L2/M2 Stundensatz\n        I8:M11 Mitarbeiter, Std-gesamt, Arbeitstage, Monate,\n                Zeitwert, Kontrollsumme, Überschuss\n    * Row 13: canonical column headers\n        A=Pos.  B=Bezeichnung  C=Menge  (D=Einheit, no header)\n        E=EP   F=GP   I=''EP | EK''   J=Min/Einheit\n        K/L=Lstg./Std.   M=''EP | EK''\n    * Row 14+: positions\n        Header rows: A=OZ, B=name, C=subtotal (computed as Σ GP of\n          following non-header rows)\n        Position rows: A=OZ, B=text, C=menge, D=einheit, E=EP, F=GP,\n          I=material EK, J=min/einheit, K=lstg/std (60/min),\n          L=lstg/std × Personaleinsatz, M=NU EK\n        Long-text → buffer row below with text in col B (matches the\n          Vorlage convention for descriptive inserts)\n    * Column widths approximated from the Vorlage so the file is\n      usable when first opened.\n\nsrc/features/kalkulation/ProjectDetail.tsx:\n  exportToExcel() now lazy-imports src/lib/kalku-xlsx/export and emits\n  Vorlage bytes. Old flat-table export (~26 lines) replaced.\n\nsrc/lib/kalku-xlsx/__tests__/export-roundtrip.test.ts — new:\n  6 tests, all pass:\n   - sheet named ''Kalkulation''\n   - header anchors at A2/A4/A6/A8/C8/C9/C10 land verbatim (re-import\n     activates the Kalkulation-template fast-path, not the generic\n     mapping wizard)\n   - row-13 column headers land verbatim\n   - meta round-trips through parseKalkulationWorkbook\n   - CalcParams (Mittellohn, Stundensatz, ZSCHLG, MwSt) round-trip\n   - positions (1 header + 2 data rows) round-trip with values within\n     2-decimal rounding\n   - no formula errors in exported file → import gate allows it\n     (PART F gate stays passive; only blocks files with #VALUE!/#REF!)\n\nTotal tests: 57/57 frontend, 51/51 backend, 1/1 e2e — 109 green.","tree":{"sha":"6fbb71604f0751cfc28fb6f36ed4d02a95023e24","url":"https://api.github.com/repos/manigolchin/kalkuweb/git/trees/6fbb71604f0751cfc28fb6f36ed4d02a95023e24"},"url":"https://api.github.com/repos/manigolchin/kalkuweb/git/commits/d64afb6da728e19b362c35b0851549ab1e3183e4","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4","events_url":"https://api.github.com/users/kalku-tech/events{/privacy}","followers_url":"https://api.github.com/users/kalku-tech/followers","following_url":"https://api.github.com/users/kalku-tech/following{/other_user}","gists_url":"https://api.github.com/users/kalku-tech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kalku-tech","id":178138257,"login":"kalku-tech","node_id":"U_kgDOCp4skQ","organizations_url":"https://api.github.com/users/kalku-tech/orgs","received_events_url":"https://api.github.com/users/kalku-tech/received_events","repos_url":"https://api.github.com/users/kalku-tech/repos","site_admin":false,"starred_url":"https://api.github.com/users/kalku-tech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kalku-tech/subscriptions","type":"User","url":"https://api.github.com/users/kalku-tech","user_view_type":"public"},"html_url":"https://github.com/manigolchin/kalkuweb/commit/d64afb6da728e19b362c35b0851549ab1e3183e4","node_id":"C_kwDOSddkS9oAKGQ2NGFmYjZkYTcyOGUxOWIzNjJjMzViMDg1MTU0OWFiMWUzMTgzZTQ","parents":[{"html_url":"https://github.com/manigolchin/kalkuweb/commit/d1758fd7a0f8a87623526dfd2d9fcdf1ef40a73b","sha":"d1758fd7a0f8a87623526dfd2d9fcdf1ef40a73b","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/d1758fd7a0f8a87623526dfd2d9fcdf1ef40a73b"}],"sha":"d64afb6da728e19b362c35b0851549ab1e3183e4","url":"https://api.github.com/repos/manigolchin/kalkuweb/commits/d64afb6da728e19b362c35b0851549ab1e3183e4"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/178138257?v=4