do em docs/context/.","tree":{"sha":"03db0be58f32234324337124268baa521a7d5a0d","url":"https://api.github.com/repos/robertourias/scaffold-ia-projetos/git/trees/03db0be58f32234324337124268baa521a7d5a0d"},"url":"https://api.github.com/repos/robertourias/scaffold-ia-projetos/git/commits/3e40b9a45b9705cabc2c37281d04a22597245d14","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/2049373?v=4","events_url":"https://api.github.com/users/robertourias/events{/privacy}","followers_url":"https://api.github.com/users/robertourias/followers","following_url":"https://api.github.com/users/robertourias/following{/other_user}","gists_url":"https://api.github.com/users/robertourias/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/robertourias","id":2049373,"login":"robertourias","node_id":"MDQ6VXNlcjIwNDkzNzM=","organizations_url":"https://api.github.com/users/robertourias/orgs","received_events_url":"https://api.github.com/users/robertourias/received_events","repos_url":"https://api.github.com/users/robertourias/repos","site_admin":false,"starred_url":"https://api.github.com/users/robertourias/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/robertourias/subscriptions","type":"User","url":"https://api.github.com/users/robertourias","user_view_type":"public"},"html_url":"https://github.com/robertourias/scaffold-ia-projetos/commit/3e40b9a45b9705cabc2c37281d04a22597245d14","node_id":"C_kwDOSdozz9oAKDNlNDBiOWE0NWI5NzA1Y2FiYzJjMzcyODFkMDRhMjI1OTcyNDVkMTQ","parents":[{"html_url":"https://github.com/robertourias/scaffold-ia-projetos/commit/47e74718890f7f21e1aa78bf892f1a2acc4346a5","sha":"47e74718890f7f21e1aa78bf892f1a2acc4346a5","url":"https://api.github.com/repos/robertourias/scaffold-ia-projetos/commits/47e74718890f7f21e1aa78bf892f1a2acc4346a5"},{"html_url":"https://github.com/robertourias/scaffold-ia-projetos/commit/dd60ef513f7