INSERT INTO collection_pages VALUES('c3cefcac6968f8c271148c67bec0e5b3c0dd485d824bb1b20e74674a3b6b8c55','1ebe6db350ad51b853498c7f2a5e637aefdaf02757cc91c52f4fc2f3b787b6bb','{"hasNext":false,"items":[{"author":{"account":{"login":"levoel","providerType":"User"},"email":"neganovlevs@gmail.com","name":"列夫"},"authoredDate":"2026-05-15T18:08:02Z","committedDate":"2026-05-15T18:08:02Z","committer":{"account":{"login":"levoel","providerType":"User"},"email":"neganovlevs@gmail.com","name":"列夫"},"observedAt":"2026-10-08T23:02:39.543Z","repositoryId":1240053807,"sha":"a515c9b615c5fe2bb9465dc51819ba66d93c8e64"}],"observedAt":"2026-10-08T23:02:39.543Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/26579249?v=4","events_url":"https://api.github.com/users/levoel/events{/privacy}","followers_url":"https://api.github.com/users/levoel/followers","following_url":"https://api.github.com/users/levoel/following{/other_user}","gists_url":"https://api.github.com/users/levoel/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/levoel","id":26579249,"login":"levoel","node_id":"MDQ6VXNlcjI2NTc5MjQ5","organizations_url":"https://api.github.com/users/levoel/orgs","received_events_url":"https://api.github.com/users/levoel/received_events","repos_url":"https://api.github.com/users/levoel/repos","site_admin":false,"starred_url":"https://api.github.com/users/levoel/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/levoel/subscriptions","type":"User","url":"https://api.github.com/users/levoel","user_view_type":"public"},"comments_url":"https://api.github.com/repos/levoel/rest-api-fundamentals/commits/a515c9b615c5fe2bb9465dc51819ba66d93c8e64/comments","commit":{"author":{"date":"2026-05-15T18:08:02Z","email":"neganovlevs@gmail.com","name":"列夫"},"comment_count":0,"committer":{"date":"2026-05-15T18:08:02Z","email":"neganovlevs@gmail.com","name":"列夫"},"message":"feat: initial REST API & Data Formats course\n\nПолный курс для Junior Data Engineer:\n- 14 модулей, 51 урок (~75000 слов контента)\n- 65 quiz-файлов (per-lesson + module exams)\n- 86 терминов глоссария, 44 troubleshooting-сценария\n- 4 hands-on лабы (HTTP deep-dive, resilient client, OpenAPI codegen, capstone ETL)\n- README, MIT для контента / Apache 2.0 для examples\n\nПокрытие: HTTP (1.1/2/3, кэширование, CORS), JSON/CSV/YAML/XML/JSONL/MessagePack,\nREST design + RFC 7807, requests/httpx (sync/async, retries), OpenAPI 3.1,\nOAuth2/JWT/PKCE, pagination/rate-limits/circuit-breaker, GraphQL/gRPC обзор,\nwebhooks/SSE/WebSocket, Avro/Parquet, тестирование (pytest/responses/VCR/Pact),\nmulti-source ETL capstone.\n\nВерсии: requests 2.34, httpx 0.28, Python 3.13, OpenAPI 3.1, pyarrow 17+\n\nCo-Authored-By: Claude Opus 4.7 (1M context) <noreply@anthropic.com>","tree":{"sha":"27c825071fac37133c49542864d1f61206be6472","url":"https://api.github.com/repos/levoel/rest-api-fundamentals/git/trees/27c825071fac37133c49542864d1f61206be6472"},"url":"https://api.github.com/repos/levoel/rest-api-fundamentals/git/commits/a515c9b615c5fe2bb9465dc51819ba66d93c8e64","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/26579249?v=4","events_url":"https://api.github.com/users/levoel/events{/privacy}","followers_url":"https://api.github.com/users/levoel/followers","following_url":"https://api.github.com/users/levoel/following{/other_user}","gists_url":"https://api.github.com/users/levoel/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/levoel","id":26579249,"login":"levoel","node_id":"MDQ6VXNlcjI2NTc5MjQ5","organizations_url":"https://api.github.com/users/levoel/orgs","received_events_url":"https://api.github.com/users/levoel/received_events","repos_url":"https://api.github.com/users/levoel/repos","site_admin":false,"starred_url":"https://api.github.com/users/levoel/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/user